<script setup lang="ts">
import {computed} from 'vue';
const props=defineProps<{kind:string;data:any;schedules:any[];only?:string[]|null;fillable?:boolean}>();
defineEmits<{select:[id:string];fill:[id:string]}>();
const plan=computed(()=>props.data.plan||{});
const stores=computed(()=>{const map=new Map();for(const s of props.schedules){if(props.only&&!props.only.includes(s.store_id))continue;map.set(s.store_id,{...s.store,id:s.store_id,date:s.activity_date});}return [...map.values()].sort((a,b)=>(a.store_code||'').localeCompare(b.store_code||''));});
const ids=computed(()=>new Set(stores.value.map(s=>s.id)));
const counts=(id:string)=>plan.value.headcount?.find((r:any)=>r.store_id===id);
const own=(id:string)=>(plan.value.ownStaff||[]).filter((r:any)=>r.store_id===id);
const requests=computed(()=>(plan.value.requests||[]).filter((r:any)=>ids.value.has(r.requesting_store_id)));
const assigned=(id:string)=>(plan.value.supportStaff||[]).filter((r:any)=>r.support_request_id===id);
const name=(id:string)=>{const s=stores.value.find(s=>s.id===id);return s?[s.store_code,s.store_name].join(' '):'門市資料無法讀取';};
const completion=(sid:string,id:string)=>plan.value.completions?.find((r:any)=>r.store_id===sid&&r.checklist_item_id===id);
const totals=computed(()=>stores.value.reduce((sum,s)=>{const c=counts(s.id);sum.own+=Number(c?.own_staff_count??own(s.id).length);sum.supervisor+=Number(c?.supervisor_count||0);sum.extra+=Number(c?.extra_support_count||0);sum.missing+=c?0:1;return sum;},{own:0,supervisor:0,extra:0,missing:0}));
const incomplete=computed(()=>stores.value.reduce((sum,s)=>sum+(plan.value.checklist||[]).filter((r:any)=>!completion(s.id,r.id)?.is_completed).length,0));
const keys=computed(()=>props.kind==='staff'?['headcount','ownStaff','requests','supportStaff']:props.kind==='support'?['requests','supportStaff']:props.kind==='checklist'?['checklist','completions']:['trips']);
const errors=computed(()=>keys.value.filter(k=>plan.value.errors?.[k]));
</script>
<template><div class="activity-overview"><p v-for="k in errors" :key="k" role="alert">{{plan.errors[k]}}，請關閉總覽後重新讀取規劃。</p>
<template v-if="!errors.length">
<template v-if="kind==='staff'"><p class="summary">本店 {{totals.own}} 人 · 督導 {{totals.supervisor}} 人 · 額外支援 {{totals.extra}} 人 · 合計 {{totals.own+totals.supervisor+totals.extra}} 人</p><p v-if="totals.missing">{{totals.missing}} 間尚未設定人力預估；本店人數以已安排名單計算，未設定的督導及額外支援不計入合計。</p><div class="module-table"><table><thead><tr><th>門市／日期</th><th>本店人員</th><th>督導人數</th><th>額外支援</th><th>合計</th><th>本店名單與支援來源</th><th>操作</th></tr></thead><tbody><tr v-for="s in stores" :key="s.id"><td>{{name(s.id)}}<br>{{s.date}}</td><td>{{counts(s.id)?.own_staff_count??own(s.id).length}}</td><td>{{counts(s.id)?.supervisor_count??'未設定'}}</td><td>{{counts(s.id)?.extra_support_count??'未設定'}}</td><td>{{counts(s.id)?.total??'未設定'}}</td><td><details><summary>本店名單（{{own(s.id).length}} 人）</summary><p v-for="p in own(s.id)" :key="p.id">{{p.employee_code}} {{p.employee_name}} · {{p.position||'未填職位'}}</p></details><div v-for="r in requests.filter((r:any)=>r.requesting_store_id===s.id)" :key="r.id"><p>{{r.supporting_store?.store_code}} {{r.supporting_store?.store_name}}：需求 {{r.requested_count}} 人／已指派 {{assigned(r.id).length}} 人</p><p v-for="p in assigned(r.id)" :key="p.id">{{p.employee_code}} {{p.employee_name}} · {{p.position}}</p></div><p v-if="counts(s.id)?.notes">{{counts(s.id).notes}}</p></td><td><button @click="$emit('select',s.id)">查看門市規劃</button><button v-if="fillable" data-testid="fill-people" @click="$emit('fill',s.id)">填報人力</button></td></tr></tbody></table></div></template>
<template v-else-if="kind==='support'"><p>共 {{requests.length}} 項支援需求 · 依支援門市查看前往門市、需求及指派人員。</p><div class="module-table"><table><thead><tr><th>支援來源門市</th><th>前往門市／日期</th><th>需求／已指派</th><th>指派人員</th><th>備註</th></tr></thead><tbody><tr v-for="r in [...requests].sort((a,b)=>(a.supporting_store?.store_code||'').localeCompare(b.supporting_store?.store_code||''))" :key="r.id"><td>{{r.supporting_store?.store_code}} {{r.supporting_store?.store_name}}</td><td><button @click="$emit('select',r.requesting_store_id)">{{name(r.requesting_store_id)}}</button><br>{{stores.find(s=>s.id===r.requesting_store_id)?.date}}</td><td>{{r.requested_count}}／{{assigned(r.id).length}}</td><td><p v-for="p in assigned(r.id)" :key="p.id">{{p.employee_code}} {{p.employee_name}} · {{p.position}}</p><span v-if="!assigned(r.id).length">尚未指派</span></td><td>{{r.notes||'—'}}</td></tr></tbody></table></div><p v-if="!requests.length">尚無支援請求。</p></template>
<template v-else-if="kind==='checklist'"><p>共 {{plan.checklist?.length||0}} 個前置項目 · {{stores.length}} 間排程門市 · 尚未完成 {{incomplete}} 項門市工作</p><section v-for="s in stores" :key="s.id"><h3>{{name(s.id)}} · {{s.date}} <button v-if="fillable" data-testid="fill-checklist" @click="$emit('fill',s.id)">填報 Check List</button></h3><div class="module-table"><table><thead><tr><th>工作／規劃備註</th><th>安排人員／期限</th><th>門市負責人</th><th>狀態</th><th>店長回報</th></tr></thead><tbody><tr v-for="r in plan.checklist" :key="r.id"><td>{{r.task_name}}<p>{{r.notes}}</p></td><td>{{r.assigned_person||'未指定'}}／{{r.deadline||'未設定'}}</td><td>{{completion(s.id,r.id)?.store_assigned_person||'未指定'}}</td><td>{{completion(s.id,r.id)?.is_completed?'已完成':'未完成'}}<br>{{completion(s.id,r.id)?.completed_at?.slice(0,10)}}</td><td>{{completion(s.id,r.id)?.manager_note||'尚無回報'}}</td></tr></tbody></table></div></section><p v-if="!plan.checklist?.length">尚無前置工作項目。</p></template>
<template v-else><div class="module-table"><table><thead><tr><th>日期</th><th>套次</th><th>起點</th><th>目的地</th><th>備註</th></tr></thead><tbody><tr v-for="r in plan.trips" :key="r.id"><td>{{r.trip_date}}</td><td>{{r.set_number}}</td><td>{{r.from_location}}</td><td>{{r.to_location}}</td><td>{{r.notes||'—'}}</td></tr></tbody></table></div><p v-if="!plan.trips?.length">尚無設備車次。</p></template>
<p v-if="kind!=='trips'&&!stores.length">此範圍尚無排程門市。</p>
</template></div></template>
<style scoped>.activity-overview td{vertical-align:top;white-space:normal;min-width:90px}.activity-overview p{white-space:pre-wrap;overflow-wrap:anywhere}.summary{font-weight:700}.activity-overview section{border-top:1px solid var(--line,#ddd);margin-top:20px}.activity-overview h3{font-size:16px}.activity-overview summary{cursor:pointer;padding:8px 0}</style>
